async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");

  let accepted = 0;
  let rejected = 0;
  let lineNumber = 0;
  let pending = "";
  let cancelled = false;

  const cancelOnce = async () => {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  };

  const visitLine = async (rawLine) => {
    lineNumber++;

    let line = rawLine;
    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }

    if (line.trim() === "") {
      return false;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      rejected++;
      return false;
    }

    const result = await visitor({ line: lineNumber, value });
    accepted++;

    if (result === false) {
      await cancelOnce();
      return true;
    }

    return false;
  };

  const consumeText = async (text) => {
    let start = 0;

    for (let i = 0; i < text.length; i++) {
      if (text.charCodeAt(i) === 10) {
        const line = pending + text.slice(start, i);
        pending = "";
        start = i + 1;

        if (await visitLine(line)) {
          return true;
        }
      }
    }

    pending += text.slice(start);
    return false;
  };

  try {
    while (true) {
      const result = await reader.read();

      if (result.done) {
        const tail = decoder.decode();

        if (await consumeText(tail)) {
          return { accepted, rejected, stopped: true };
        }

        if (pending.length > 0) {
          if (await visitLine(pending)) {
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      const text = decoder.decode(result.value, { stream: true });

      if (await consumeText(text)) {
        return { accepted, rejected, stopped: true };
      }
    }
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
